  compositions: [
    { group: "Wide", label: "Wide and calm", text: "The frame is wide and calm, with generous empty space around the subject." },
    { group: "Wide", label: "Establishing", text: "The frame is an establishing view that tells you where you are before any detail." },
    { group: "Wide", label: "Horizon low", text: "The horizon sits low, so the sky has the larger share of the picture." },
    { group: "Wide", label: "Horizon high", text: "The horizon sits high, and the ground becomes a broad field of texture." },
    { group: "Wide", label: "Panorama feel", text: "The frame feels panoramic, even before the aspect ratio is applied." },
    { group: "Near", label: "Close and shallow", text: "The view moves in close, with a shallow depth of field and a soft background." },
    { group: "Near", label: "Detail study", text: "The frame is a detail study: one material, one edge, one small truth." },
    { group: "Near", label: "Still life", text: "The frame is arranged like a still life, with a few objects and room to rest." },
    { group: "Near", label: "Hands-off", text: "The frame is near enough to touch, but no hands enter it." },
    { group: "Angle", label: "Eye level", text: "The camera is at a calm eye level, as if a person stopped to look." },
    { group: "Angle", label: "Low angle", text: "The camera sits low and looks slightly up, giving the subject a quiet dignity." },
    { group: "Angle", label: "High angle", text: "The camera looks gently down, reading the layout of the place." },
    { group: "Angle", label: "Overhead", text: "The camera is overhead, almost flat, like a map made of real things." },
    { group: "Angle", label: "Worm's eye", text: "The camera is near the ground, looking through grass or objects toward the distance." },
    { group: "Balance", label: "Rule of thirds", text: "The subject sits on a third, with the rest of the frame left open." },
    { group: "Balance", label: "Centered", text: "The subject is centered and symmetrical, like a formal portrait of a place." },
    { group: "Balance", label: "Off balance", text: "The weight of the picture sits to one side, and the other side breathes." },
    { group: "Balance", label: "Negative space", text: "Negative space does most of the work, and the subject is small and precise." },
    { group: "Balance", label: "Layered depth", text: "Foreground, middle, and distance are all readable, stacked in clear layers." },
    { group: "Frame", label: "Frame in frame", text: "A doorway, arch, or window frames the view beyond it." },
    { group: "Frame", label: "Natural vignette", text: "Darker foreground shapes make a natural vignette around a brighter center." },
    { group: "Frame", label: "Leading line", text: "A path, wall, or shadow leads the eye into the picture." },
    { group: "Frame", label: "Repetition", text: "A repeated shape — posts, trees, or tiles — sets a rhythm across the frame." },
    { group: "Lens", label: "Normal lens", text: "The perspective is natural, like a 50mm lens, with no drama in the distortion." },
    { group: "Lens", label: "Mild wide", text: "A mildly wide lens includes the context without bending the edges." },
    { group: "Lens", label: "Long lens", text: "A long lens stacks the distance and softens what is behind the subject." },
    { group: "Lens", label: "Deep focus", text: "Everything from the near stones to the far ridge is in focus." },
    { group: "Lens", label: "Selective focus", text: "Only one plane is sharp. The rest falls into a creamy blur." },
    { group: "Human", label: "Over the shoulder", text: "The view is placed just past a foreground silhouette, as if looking past someone, though no person is required." },
    { group: "Human", label: "Looking through", text: "The camera looks through leaves or cloth that partly veil the subject." },
    { group: "Human", label: "Corner glimpse", text: "The picture feels glimpsed from a corner, not formally posed." },
    { group: "Graphic", label: "Flat lay", text: "Objects are seen from directly above in a loose, editorial flat lay." },
    { group: "Graphic", label: "Strong diagonal", text: "A strong diagonal keeps the still picture from feeling static." },
    { group: "Graphic", label: "Minimal", text: "The composition is minimal: few shapes, lots of quiet." },
    { group: "Graphic", label: "Dense", text: "The frame is richly filled, with pattern from edge to edge." },
    { group: "Graphic", label: "Split field", text: "The picture is split into two clear fields of colour or light." },
    { group: "Place", label: "Environmental", text: "The subject is shown small inside a large, readable place." },
    { group: "Place", label: "Threshold", text: "The camera stands on a threshold, half in and half out." },
    { group: "Place", label: "Reflection", text: "A reflection in water, glass, or metal carries part of the picture." },
    { group: "Place", label: "Long approach", text: "The subject is at the end of a long approach, small and awaited." },
    { group: "Place", label: "Surround", text: "The place surrounds the middle of the frame on all sides." },
    { group: "Place", label: "Open corner", text: "One corner of the frame is left almost empty, like a margin on a page." }
  ],

