  cameras: [
    { group: "Static", label: "Static", text: "The camera stays perfectly still, like a locked-off photograph.", tip: "No camera movement at all. Only the scene itself stirs." },
    { group: "Static", label: "Static with a breath", text: "The camera is locked off, with only the tiniest living stillness of a held frame.", tip: "Almost still. Think of a person quietly holding the camera, not walking." },
    { group: "Static", label: "Tripod eye-level", text: "The camera remains fixed at eye level on a tripod.", tip: "A steady, ordinary human viewpoint that never drifts." },
    { group: "Static", label: "Low static", text: "The camera sits low and does not move, looking slightly upward.", tip: "Still camera, placed near the ground." },
    { group: "Static", label: "High static", text: "The camera looks down from above and holds completely still.", tip: "A fixed high angle, as if the camera were set on a balcony." },
    { group: "Push", label: "Slow push-in", text: "The camera slowly pushes in, easing closer as if to notice a detail.", tip: "The frame gently moves closer. Nothing else about the camera changes." },
    { group: "Push", label: "Push to a detail", text: "The camera glides forward until one small part of the scene matters more.", tip: "Starts wide enough to understand the place, then eases toward one thing." },
    { group: "Push", label: "Push through", text: "The camera moves slowly forward through the space.", tip: "Like walking into the picture, but smoother than footsteps." },
    { group: "Push", label: "Creeping push", text: "The camera creeps forward so gradually the move is felt before it is noticed.", tip: "A very slow approach. Good when the scene motion is doing most of the work." },
    { group: "Pull", label: "Pull-out", text: "The camera slowly pulls back and reveals more of the place.", tip: "The frame eases away, so the subject gets smaller and the surroundings appear." },
    { group: "Pull", label: "Reveal pull", text: "The camera starts close and retreats until the whole scene is visible.", tip: "Begins on a detail and backs up to show where that detail lives." },
    { group: "Pull", label: "Rising pull-back", text: "The camera lifts slightly as it pulls away.", tip: "You both rise and retreat, which opens the view without a sudden jump." },
    { group: "Pan", label: "Pan left", text: "The camera pans slowly to the left across the scene.", tip: "The camera turns left in place, like turning your head." },
    { group: "Pan", label: "Pan right", text: "The camera pans slowly to the right across the scene.", tip: "The camera turns right in place, scanning the view." },
    { group: "Pan", label: "Gentle sweep", text: "The camera makes one smooth sweep from one side of the scene to the other.", tip: "A single unhurried turn, not a fast whip." },
    { group: "Pan", label: "Follow pan", text: "The camera pans to follow whatever is moving in the scene.", tip: "The turn keeps the moving thing roughly in frame." },
    { group: "Tilt", label: "Tilt up", text: "The camera tilts slowly upward, from the ground toward the sky.", tip: "The camera looks up in place. It does not fly." },
    { group: "Tilt", label: "Tilt down", text: "The camera tilts slowly downward, from the upper view to the ground.", tip: "The camera looks down in place, revealing what is below." },
    { group: "Tilt", label: "Horizon settle", text: "The camera makes a small tilt and then settles level.", tip: "A tiny correction, as if finding the horizon and resting there." },
    { group: "Orbit", label: "Slow orbit", text: "The camera slowly orbits the subject and shows another side.", tip: "The camera travels around the subject instead of only turning its head." },
    { group: "Orbit", label: "Half orbit", text: "The camera travels halfway around the subject in one calm arc.", tip: "About 180 degrees, unhurried, so you see the front and then the side." },
    { group: "Orbit", label: "Tight orbit", text: "The camera circles close, keeping the subject large in frame.", tip: "A near circle. The background slides, the subject stays important." },
    { group: "Orbit", label: "Overhead arc", text: "The camera curves above the subject in a partial arc.", tip: "Not a full spin. A gentle overhead curve, like leaning over a table while walking." },
    { group: "Drone", label: "Drone fly-over", text: "The camera flies gently overhead, as if on a small drone.", tip: "A calm aerial pass above the scene, not a racing shot." },
    { group: "Drone", label: "Drone approach", text: "A drone glides in from far away and comes closer.", tip: "Starts as a wide aerial view and drifts toward the subject." },
    { group: "Drone", label: "Drone rise", text: "The camera rises straight up and reveals the layout below.", tip: "A vertical lift. The world opens underneath the lens." },
    { group: "Drone", label: "Low fly along", text: "The camera flies forward low over a path, shore, or ridge.", tip: "Moves ahead just above the ground, following the line of the place." },
    { group: "Drone", label: "High drift", text: "The camera holds a distant aerial view and drifts slowly sideways.", tip: "Far away and quiet. Good for landscapes." },
    { group: "Handheld", label: "Gentle handheld", text: "The camera is handheld, with a soft human unsteadiness.", tip: "A person is holding it. The frame breathes a little. It does not shake wildly." },
    { group: "Handheld", label: "Walking handheld", text: "The camera walks forward at shoulder height with natural steps in the movement.", tip: "You feel footsteps, but the picture stays readable." },
    { group: "Handheld", label: "Look around", text: "The holder glances around the space in a loose, curious way.", tip: "Small turns of attention, as if noticing the room." },
    { group: "Handheld", label: "Shoulder follow", text: "The camera follows just behind the action at shoulder height.", tip: "A following view. If nothing walks, it simply trails through the place." },
    { group: "Dolly zoom", label: "Dolly zoom", text: "The camera moves closer while zooming out, so the subject stays a similar size and the background stretches.", tip: "A dreamlike stretch. The middle stays put while the world behind it warps. Use it sparingly." },
    { group: "Dolly zoom", label: "Soft dolly zoom", text: "The camera eases forward and zooms out only a little, for a mild uneasy stretch.", tip: "A gentler version of the dolly zoom. The effect should be felt, not shouted." },
    { group: "Dolly zoom", label: "Reverse dolly zoom", text: "The camera pulls back while zooming in, so the background seems to compress.", tip: "The opposite stretch. The world behind the subject appears to tighten." },
    { group: "Other", label: "Lateral slide", text: "The camera slides sideways without turning, like looking from a slow train.", tip: "A straight side move. The camera does not pan. Near things pass faster than far things." },
    { group: "Other", label: "Crane down", text: "The camera lowers smoothly from a high view to eye level.", tip: "A controlled descent, as if on a small crane." },
    { group: "Other", label: "Crane up", text: "The camera rises smoothly from the ground to a high view.", tip: "A controlled rise that opens the scene." },
    { group: "Other", label: "Focus drift", text: "The camera barely moves, and the focus slips from something near to something far.", tip: "The drama is the change in focus, not a big camera move." },
    { group: "Other", label: "Pass by", text: "The camera travels past the subject and leaves it behind.", tip: "The subject enters importance and then slides out of the frame." },
    { group: "Other", label: "Straight rise", text: "The camera moves straight up without tilting.", tip: "Called a pedestal. The angle stays the same. Only the height changes." },
    { group: "Other", label: "Slight dutch drift", text: "The horizon tips a little as the camera slowly drifts.", tip: "A small tilt of the horizon for a restless feeling. It should not turn fully sideways." }
  ],

